//! The translations of the website, generated by build.rs from `locales/` at the workspace root.
//! A crate of its own: the generated code only compiles again when the translations change, not
//! with every edit of the website.

/// Not our code: exempt from the strict workspace lints
#[allow(
    clippy::all,
    clippy::pedantic,
    clippy::nursery,
    rust_2018_idioms,
    unused_qualifications,
    unreachable_pub,
    missing_debug_implementations,
    trivial_casts,
    trivial_numeric_casts
)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/i18n/mod.rs"));
}
pub use generated::i18n;
